    @Test public void fuzzyLocationIsCapturedAsEvidenceAndOnlyTheChosenExactTextCanEnterOriginalApproval()throws Exception{
        JSONObject schema=null;JSONArray tools=port.tools();for(int i=0;i<tools.length();i++){JSONObject function=tools.getJSONObject(i).getJSONObject("function");if("project_search".equals(function.getString("name")))schema=function.getJSONObject("parameters");}
        assertNotNull(schema);assertTrue(schema.getJSONObject("properties").getJSONObject("syntax").getJSONArray("enum").toString().contains("\"fuzzy\""));assertEquals(2,schema.getJSONObject("properties").getJSONObject("maxEdits").getInt("maximum"));assertFalse(port.sideEffecting("project_search"));
        JSONObject input=new JSONObject().put("mode","text").put("syntax","fuzzy").put("query","sourcf").put("contextAfter",1);port.validate("project_search",input);
        var binding=new ModelCapabilityAdapters.Binding(task,run,epoch,original,true,project);JSONObject match;
        try(var captured=new ProjectCapabilityPort(binding,new TaskStoreCapabilityAuthority(tasks,binding,event->{}),original,null,local,tasks,checkout,"termux",tasks.toolOutputFactory(task,run,epoch,original,text->text))){
            JSONObject result=captured.execute("project_search",input,original);assertTrue(result.getBoolean("suggestionOnly"));assertFalse(result.getBoolean("writeAuthorityAdded"));assertEquals(1,result.getJSONArray("matches").length());match=result.getJSONArray("matches").getJSONObject(0);
            assertEquals("source.txt",match.getString("path"));assertEquals(1,match.getInt("editDistance"));assertEquals(1,match.getInt("column"));assertEquals(7,match.getInt("endColumn"));assertEquals(sha("source 中文🙂\n"),match.getString("sha256"));
            JSONObject ref=result.getJSONObject("outputCapture").getJSONArray("outputRefs").getJSONObject(0);assertEquals(task,ref.getString("taskId"));assertEquals("project_search",ref.getString("tool"));assertEquals("",ref.getString("operationId"));
            var field=TaskStore.class.getDeclaredField("db");field.setAccessible(true);StringBuilder body=new StringBuilder();try(android.database.Cursor rows=((SQLiteDatabase)field.get(tasks)).rawQuery("SELECT body FROM task_output_chunks ORDER BY rowid",null)){while(rows.moveToNext())body.append(rows.getString(0));}assertTrue(body.toString().contains(match.getString("sha256")));assertTrue(body.toString().contains("editDistance"));
        }
        assertEquals(0,tasks.get(task,false).getJSONArray("operations").length());assertEquals("source 中文🙂\n",readUtf8(files.resolve("source.txt")));
        JSONObject read=port.execute("project_read_file",new JSONObject().put("path",match.getString("path")).put("expectedHash",match.getString("sha256")),original);assertEquals("source 中文🙂\n",read.getString("content"));
        JSONObject edit=new JSONObject().put("path",match.getString("path")).put("expectedHash",match.getString("sha256")).put("replacements",new JSONArray().put(new JSONObject().put("oldText","sourcf").put("newText","selected").put("startOffset",0)));
        assertEquals("project_plan_rejected",propose(new JSONArray().put(edit)).getString("code"));assertEquals(0,tasks.get(task,false).getJSONArray("operations").length());
        edit.getJSONArray("replacements").getJSONObject(0).put("oldText","source");JSONObject args=arguments(propose(new JSONArray().put(edit)));approve(args);JSONObject receipt=dispatchApproved(args);
        assertEquals("completed",receipt.getString("status"));assertTrue(receipt.getBoolean("receiptReceived"));assertEquals("selected 中文🙂\n",readUtf8(files.resolve("source.txt")));assertEquals(sha("selected 中文🙂\n"),receipt.getJSONArray("files").getJSONObject(0).getString("actualAfterHash"));assertFalse(tasks.hasUnresolved(task));assertEquals(1,tasks.list().length());assertEquals(2,tasks.get(task,false).getJSONArray("operations").length());
        assertEquals("source 中文🙂\n",workspace.handle("read",new JSONObject().put("projectId",project).put("path","source.txt")).getString("content"));
    }
