        tasks.authorizeTools(task,run,new JSONArray().put("project_inspect").put("project_read_file").put("project_search").put("project_list_files").put("project_package").put("project_plan").put("project_execute"));Files.write(files.resolve("asset-source.bin"),HEX_BEFORE);JSONObject copiedArgs=arguments(propose(new JSONArray().put(rawCopyEdit("assets/copied.bin"))));approve(copiedArgs);assertEquals("completed",dispatchApproved(copiedArgs).getString("status"));JSONObject hexArgs=arguments(propose(new JSONArray().put(hexEdit().put("path","assets/copied.bin"))));approve(hexArgs);assertEquals("completed",dispatchApproved(hexArgs).getString("status"));byte[] frozenBytes={0,(byte)255,0,3,4};assertArrayEquals(frozenBytes,Files.readAllBytes(files.resolve("assets/copied.bin")));
        JSONObject frozen=port.execute("project_plan",new JSONObject().put("intent","freeze_package").put("expectedSourceDigest",digest()).put("packageMode","source_project"),original);JSONObject freezeArgs=new JSONObject().put("planRef",frozen.getString("planRef")).put("planDigest",frozen.getString("planDigest")).put("stepId","freeze_package");approve(freezeArgs);JSONObject settled=dispatchApproved(freezeArgs);assertEquals(settled.toString(),"completed",settled.getString("status"));assertFalse(settled.getBoolean("businessVerified"));JSONObject packageResult=port.execute("project_package",new JSONObject().put("executionId",settled.getString("operationId")),original);String id=packageResult.getString("artifactId"),sha=packageResult.getString("archiveSha256");assertTrue(packageResult.getBoolean("immutable"));assertFalse(packageResult.getBoolean("authorityAdded"));assertFalse(packageResult.getBoolean("automaticallyExported"));
        Files.write(files.resolve("assets/copied.bin"),new byte[]{7,7});java.io.ByteArrayOutputStream archive=new java.io.ByteArrayOutputStream();local.exportProjectPackageForOwner(id,sha,archive);assertEquals(sha,ProjectSources.sha256(archive.toByteArray()));FeatureContext context=new FeatureContext(RuntimeEnvironment.getApplication(),null,null,event->{});try(LocalModule cold=new LocalModule(context,workspace,new NoProcess())){String selection=UUID.randomUUID().toString();JSONObject staged=cold.stageProjectPackageForOwner(new java.io.ByteArrayInputStream(archive.toByteArray()),selection),review=cold.planProjectPackageImportForOwner(selection,staged.getString("sha256"),"Explicit original binary package reopen",null),imported=cold.importProjectPackageForOwner(review.getJSONObject("plan"));String reopened=imported.getString("id");assertNotEquals(checkout,reopened);assertNotEquals(project,imported.getString("projectId"));assertFalse(imported.getBoolean("taskOrGrantRestored"));assertFalse(imported.getJSONObject("sourceImport").getBoolean("executionAuthorityRestored"));Path restored=files.getParent().getParent().resolve(reopened).resolve("files");assertArrayEquals(frozenBytes,Files.readAllBytes(restored.resolve("assets/copied.bin")));assertArrayEquals(HEX_BEFORE,Files.readAllBytes(restored.resolve("asset-source.bin")));assertArrayEquals(new byte[]{7,7},Files.readAllBytes(files.resolve("assets/copied.bin")));assertEquals(1,tasks.list().length());assertEquals(run,tasks.get(task,false).getString("runId"));assertEquals(checkout,tasks.get(task,false).getJSONObject("developmentContext").getString("checkoutId"));assertFalse(tasks.hasUnresolved(task));}
